ret = texture(sampler_main,uv).xyz;
vec3 colc = lum(ret - GetBlur2(uv)*.1) * 2.0;
vec3 colc2 = lum(ret - GetBlur2(uv)*.1) * 2.0;
colc = pow(colc*(ret * 10.0),(ret*colc) * 50.0);
ret *= mix((colc2)-colc * 5.0,(colc)*colc,ret)+GetBlur3(uv) * 50.0;
ret = vec3(abs((rad * 10.0*q2) - 1.0)*ret.x,abs((rad * 10.0*q1) - 1.0)*ret.y,abs((rad * 10.0*q3) - 1.0)*ret.z);
